    // 1. Prepare selected department/class keys (IDs and names)
    const selDepts = (Array.isArray(this.userFilters.department_id) ? this.userFilters.department_id : [this.userFilters.department_id]).filter(Boolean).map(v => String(v).toLowerCase().trim());
    const hasDeptFilter = selDepts.length > 0 && !this.isAllDepartmentsSelected();
